static inline const lv_image_dsc_t* uiIcon_globe_lg() {
    static lv_image_dsc_t d{};
    static bool ok = false;
    if (!ok) {
        d.header.magic = LV_IMAGE_HEADER_MAGIC;
        d.header.cf = LV_COLOR_FORMAT_A8;
        d.header.w = 52; d.header.h = 52; d.header.stride = 52;
        d.data_size = sizeof(ui_ico_globe_lg_map);
        d.data = ui_ico_globe_lg_map;
        ok = true;
    }
    return &d;
}


static inline lv_obj_t* uiCreateIconImg(lv_obj_t *parent, const lv_image_dsc_t *dsc, uint32_t hexCol) {
    lv_obj_t *img = lv_image_create(parent);
    lv_image_set_src(img, dsc);
    lv_obj_set_style_image_recolor(img, lv_color_hex(hexCol), LV_PART_MAIN);
    lv_obj_set_style_image_recolor_opa(img, LV_OPA_COVER, LV_PART_MAIN);
    lv_obj_remove_flag(img, LV_OBJ_FLAG_CLICKABLE);
    return img;
}

// Shared BT number line (CONTROL / EVENT pages): [large integer][.d ~7/10][°C right after], left aligned, same text baseline
// The label bottom shifts by the font base_line difference from the integer font; baseOfs = distance from the baseline to the bottom edge of the container
static inline void uiBtRowLayout(lv_obj_t *lblInt, lv_obj_t *lblDec, lv_obj_t *lblUnit,
                                 const lv_font_t *fInt, const lv_font_t *fDec, const lv_font_t *fUnit, int32_t baseOfs) {
    if (!lblInt || !lblDec || !lblUnit) return;
    const char *ti = lv_label_get_text(lblInt);
    const char *td = lv_label_get_text(lblDec);
    const int32_t w1 = lv_text_get_width(ti, (uint32_t)strlen(ti), fInt, 0);
    const int32_t w2 = lv_text_get_width(td, (uint32_t)strlen(td), fDec, 0);
    lv_obj_align(lblInt,  LV_ALIGN_BOTTOM_LEFT, 0,           baseOfs);
    lv_obj_align(lblDec,  LV_ALIGN_BOTTOM_LEFT, w1,          baseOfs + (int32_t)fDec->base_line  - (int32_t)fInt->base_line);
    lv_obj_align(lblUnit, LV_ALIGN_BOTTOM_LEFT, w1 + w2 + 3, baseOfs + (int32_t)fUnit->base_line - (int32_t)fInt->base_line);
}
// BT number color: cold (blue) -> hot (red) by °C from UI_TEMP_COLOR_FROM to UI_TEMP_COLOR_TO; red at and above the overheat level
static inline lv_color_t uiBtColor(float btC, float overheatC) {
    if (btC >= overheatC) return lv_color_hex(UI_HEX_RED);
    float k = (btC - (float)UI_TEMP_COLOR_FROM) / (float)(UI_TEMP_COLOR_TO - UI_TEMP_COLOR_FROM);
    k = k < 0.0f ? 0.0f : (k > 1.0f ? 1.0f : k);
    return lv_color_hsv_to_rgb((uint16_t)(215.0f * (1.0f - k)), 95, 100);
}

static inline void uiSetIconColor(lv_obj_t *img, uint32_t hexCol) {
    if (!img) return;
    lv_obj_set_style_image_recolor(img, lv_color_hex(hexCol), LV_PART_MAIN);
    lv_obj_set_style_image_recolor_opa(img, LV_OPA_COVER, LV_PART_MAIN);
}


// 5-level battery on the top bar (no % shown)
// < 2 levels (0..1 bar) -> Red | level 2 -> Orange | level 3 and up (3..5 bars) -> Green
struct UiBatteryWidget {
    lv_obj_t *frame    = nullptr;
    lv_obj_t *nub      = nullptr;
    lv_obj_t *segs[5]  = {nullptr, nullptr, nullptr, nullptr, nullptr};
    int       lastLvl  = -1;
    int       lastDisp = -1;
    bool      lastChg  = false;
    int       lastPhase = 0;
};

