static inline UiBatteryWidget uiCreateBattery5(lv_obj_t *parent) {
    UiBatteryWidget b{};
#if !UI_SHOW_BATTERY
    (void)parent;
    return b;   // battery hidden: no widget created (frame = nullptr so uiUpdateBattery5 exits by itself)
#else
    lv_obj_t *wrap = lv_obj_create(parent);
    lv_obj_remove_style_all(wrap);
    lv_obj_set_size(wrap, 50, 18);
    lv_obj_align(wrap, LV_ALIGN_RIGHT_MID, 0, 0);
    lv_obj_remove_flag(wrap, LV_OBJ_FLAG_CLICKABLE);
    lv_obj_remove_flag(wrap, LV_OBJ_FLAG_SCROLLABLE);

    // No lightning icon: while charging, the inner battery bars blink slowly (see uiUpdateBattery5)

    b.frame = lv_obj_create(wrap);
    lv_obj_remove_style_all(b.frame);
    lv_obj_set_size(b.frame, 35, 16);
    lv_obj_align(b.frame, LV_ALIGN_RIGHT_MID, -3, 0);
    lv_obj_set_style_radius(b.frame, 3, LV_PART_MAIN);
    lv_obj_set_style_bg_color(b.frame, lv_color_hex(UI_HEX_BG), LV_PART_MAIN);
    lv_obj_set_style_bg_opa(b.frame, LV_OPA_COVER, LV_PART_MAIN);
    lv_obj_set_style_border_width(b.frame, 1, LV_PART_MAIN);
    lv_obj_set_style_border_color(b.frame, lv_color_hex(UI_HEX_TEXT_SUB), LV_PART_MAIN);
    lv_obj_remove_flag(b.frame, LV_OBJ_FLAG_CLICKABLE);
    lv_obj_remove_flag(b.frame, LV_OBJ_FLAG_SCROLLABLE);

    b.nub = lv_obj_create(wrap);
    lv_obj_remove_style_all(b.nub);
    lv_obj_set_size(b.nub, 3, 8);
    lv_obj_align(b.nub, LV_ALIGN_RIGHT_MID, 0, 0);
    lv_obj_set_style_radius(b.nub, 1, LV_PART_MAIN);
    lv_obj_set_style_bg_color(b.nub, lv_color_hex(UI_HEX_TEXT_SUB), LV_PART_MAIN);
    lv_obj_set_style_bg_opa(b.nub, LV_OPA_COVER, LV_PART_MAIN);
    lv_obj_remove_flag(b.nub, LV_OBJ_FLAG_CLICKABLE);

    // 5 inner battery bars (each 4x10 px, 2 px apart -> 2 + 5*4 + 4*2 = 30 px inside 33 px)
    for (int i = 0; i < 5; ++i) {
        b.segs[i] = lv_obj_create(b.frame);
        lv_obj_remove_style_all(b.segs[i]);
        lv_obj_set_size(b.segs[i], 4, 10);
        lv_obj_set_pos(b.segs[i], 2 + i * 6, 2);
        lv_obj_set_style_radius(b.segs[i], 1, LV_PART_MAIN);
        lv_obj_set_style_bg_color(b.segs[i], lv_color_hex(UI_HEX_GREEN), LV_PART_MAIN);
        lv_obj_set_style_bg_opa(b.segs[i], LV_OPA_COVER, LV_PART_MAIN);
        lv_obj_remove_flag(b.segs[i], LV_OBJ_FLAG_CLICKABLE);
    }
    return b;
#endif
}

static inline void uiUpdateBattery5(UiBatteryWidget &b, int batPct, bool chg) {
    if (!b.frame) return;
    int lvl = 0;
    if (batPct >= 85)      lvl = 5;
    else if (batPct >= 65) lvl = 4;
    else if (batPct >= 45) lvl = 3;
    else if (batPct >= 25) lvl = 2;
    else if (batPct >= 6)  lvl = 1;
    else                   lvl = 0;

    // While charging: keep the real bar count (at least 1 bar); bars blink slowly bright / dim (~0.8 s per phase)
    int dispLvl = lvl;
    int phase   = 0;
    if (chg) {
        if (dispLvl < 1) dispLvl = 1;
        phase = static_cast<int>((millis() / 800UL) & 1UL);
    }

    if (lvl == b.lastLvl && dispLvl == b.lastDisp && chg == b.lastChg && phase == b.lastPhase) return;
    b.lastLvl   = lvl;
    b.lastDisp  = dispLvl;
    b.lastChg   = chg;
    b.lastPhase = phase;

    uint32_t col = chg ? UI_HEX_GREEN
                       : ((lvl < 2) ? UI_HEX_RED : ((lvl >= 3) ? UI_HEX_GREEN : UI_HEX_ORANGE));
    uint32_t bdr = chg ? UI_HEX_GREEN
                       : ((lvl < 2) ? UI_HEX_RED : UI_HEX_TEXT_SUB);
    lv_obj_set_style_border_color(b.frame, lv_color_hex(bdr), LV_PART_MAIN);
    if (b.nub) lv_obj_set_style_bg_color(b.nub, lv_color_hex(bdr), LV_PART_MAIN);

    for (int i = 0; i < 5; ++i) {
        if (!b.segs[i]) continue;
        if (i < dispLvl) {
            lv_obj_remove_flag(b.segs[i], LV_OBJ_FLAG_HIDDEN);
            lv_obj_set_style_bg_color(b.segs[i], lv_color_hex(col), LV_PART_MAIN);
            lv_obj_set_style_bg_opa(b.segs[i], (chg && phase) ? LV_OPA_20 : LV_OPA_COVER, LV_PART_MAIN);
        } else {
            lv_obj_add_flag(b.segs[i], LV_OBJ_FLAG_HIDDEN);
        }
    }
}

