// Center the lblMid label (IP address or MM:SS clock) in the gap between the left title and the right battery group
static inline void uiShellCenterMid(UiShell &shell) {
    if (!shell.topBar || !shell.lblLeft || !shell.lblMid) return;
    lv_obj_set_style_text_font(shell.lblMid, UI_FONT_T4, LV_PART_MAIN);
    lv_obj_update_layout(shell.topBar);
    const int32_t padH       = UI_MARGIN + 2;
    const int32_t innerW     = UI_SCR_W - padH * 2;
    const int32_t leftW      = lv_obj_get_width(shell.lblLeft);
    const int32_t batW       = UI_SHOW_BATTERY ? 50 : 0; // fixed width of the battery group (0 when the battery is hidden)
    const int32_t rightStart = innerW - batW;
    const int32_t gapW       = rightStart - leftW;
    int32_t midW             = lv_obj_get_width(shell.lblMid);
    if (midW > gapW - 2) {
        lv_obj_set_style_text_font(shell.lblMid, UI_FONT_T5, LV_PART_MAIN);
        lv_obj_update_layout(shell.topBar);
        midW = lv_obj_get_width(shell.lblMid);
    }
#if UI_SHOW_BATTERY
    // Center of the SCREEN (x = 120): text center equidistant from the 240 px edges; if it overlaps the left label / battery group, shift into the gap
    int32_t x = (UI_SCR_W / 2 - padH) - midW / 2;
    if (x > rightStart - midW - 2) x = rightStart - midW - 2;
#else
    // Battery hidden (UI_SHOW_BATTERY 0): time / IP moves to the right edge where the battery used to be
    int32_t x = rightStart - midW;
#endif
    if (x < leftW + 2) x = leftW + 2;
    lv_obj_align(shell.lblMid, LV_ALIGN_LEFT_MID, x, 0);
}

static inline void uiUpdateTopClock(UiShell &shell, bool clockSynced, const char *clockStr) {
    if (!shell.lblMid) return;
    const char *want = (clockSynced && clockStr && clockStr[0]) ? clockStr : "";
    if (strcmp(lv_label_get_text(shell.lblMid), want) != 0) {
        lv_obj_set_style_text_color(shell.lblMid, lv_color_hex(UI_HEX_TEXT), LV_PART_MAIN);
        lv_label_set_text(shell.lblMid, want);
        if (want[0]) uiShellCenterMid(shell);
    }
}


// 2. Tactile Modern button (R=7 px, thin 2 px LED bar at the bottom, pressed-key effect)
static inline UiToneBtn uiCreateToneBtn(lv_obj_t *parent, int32_t w, int32_t h, UiTone tone) {
    UiToneBtn tb{};
    tb.tone = tone;
    lv_color_t toneCol = uiToneColor(tone);

    tb.btn = lv_button_create(parent);
    lv_obj_remove_style_all(tb.btn);
    lv_obj_set_size(tb.btn, w, h);
    lv_obj_set_style_radius(tb.btn, UI_RADIUS, LV_PART_MAIN);
    lv_obj_set_style_clip_corner(tb.btn, true, LV_PART_MAIN);
    lv_obj_set_style_bg_color(tb.btn, lv_color_hex(UI_HEX_CARD), LV_PART_MAIN);
    lv_obj_set_style_bg_opa(tb.btn, LV_OPA_COVER, LV_PART_MAIN);
    lv_obj_set_style_border_width(tb.btn, 1, LV_PART_MAIN);
    lv_obj_set_style_border_color(tb.btn, lv_color_hex(UI_HEX_BORDER), LV_PART_MAIN);
    lv_obj_set_style_pad_all(tb.btn, 0, LV_PART_MAIN);
    lv_obj_remove_flag(tb.btn, LV_OBJ_FLAG_SCROLLABLE);

    // Pressed state: slightly lighter fill + border in the same tone + 1 px sink
    lv_obj_set_style_bg_color(tb.btn, lv_color_hex(UI_HEX_CARD_PRESS), LV_PART_MAIN | LV_STATE_PRESSED);
    lv_obj_set_style_border_color(tb.btn, toneCol, LV_PART_MAIN | LV_STATE_PRESSED);
    lv_obj_set_style_border_width(tb.btn, 2, LV_PART_MAIN | LV_STATE_PRESSED);
    lv_obj_set_style_translate_y(tb.btn, 1, LV_PART_MAIN | LV_STATE_PRESSED);

    // Thin 2 px LED bar at the bottom edge
    tb.ledBar = lv_obj_create(tb.btn);
    lv_obj_remove_style_all(tb.ledBar);
    lv_obj_add_flag(tb.ledBar, LV_OBJ_FLAG_IGNORE_LAYOUT);
    lv_obj_remove_flag(tb.ledBar, LV_OBJ_FLAG_CLICKABLE);
    lv_obj_remove_flag(tb.ledBar, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_set_size(tb.ledBar, LV_PCT(100), UI_LED_H);
    lv_obj_align(tb.ledBar, LV_ALIGN_BOTTOM_MID, 0, 0);
    lv_obj_set_style_bg_color(tb.ledBar, toneCol, LV_PART_MAIN);
    lv_obj_set_style_bg_opa(tb.ledBar, LV_OPA_COVER, LV_PART_MAIN);
    lv_obj_add_flag(tb.ledBar, LV_OBJ_FLAG_HIDDEN);

    return tb;
}

static inline void uiToneBtnSetTone(UiToneBtn &tb, UiTone newTone) {
    tb.tone = newTone;
    lv_color_t c = uiToneColor(newTone);
    if (tb.btn) lv_obj_set_style_border_color(tb.btn, c, LV_PART_MAIN | LV_STATE_PRESSED);
    if (tb.ledBar) lv_obj_set_style_bg_color(tb.ledBar, c, LV_PART_MAIN);
}

static inline void uiToneBtnSetBar(const UiToneBtn &tb, bool showBar, bool brightBorder = false) {
    if (!tb.btn || !tb.ledBar) return;
    (void)showBar;   // LED bar removed: the on state is shown only by border + tinted fill
    lv_obj_add_flag(tb.ledBar, LV_OBJ_FLAG_HIDDEN);

    if (brightBorder) {
        lv_obj_set_style_bg_color(tb.btn, uiToneTintColor(tb.tone), LV_PART_MAIN);
        lv_obj_set_style_border_color(tb.btn, uiToneColor(tb.tone), LV_PART_MAIN);
        lv_obj_set_style_border_width(tb.btn, 2, LV_PART_MAIN);
    } else {
        lv_obj_set_style_bg_color(tb.btn, lv_color_hex(UI_HEX_CARD), LV_PART_MAIN);
        lv_obj_set_style_border_color(tb.btn, lv_color_hex(UI_HEX_BORDER), LV_PART_MAIN);
        lv_obj_set_style_border_width(tb.btn, 1, LV_PART_MAIN);
    }
}

static inline void uiToneBtnSetOn(const UiToneBtn &tb, bool on) {
    uiToneBtnSetBar(tb, on, on);
}

// Solid bright single-color button (END / ± style in the Heater, Air popups): solid fill + border; darkens 20% when pressed. Text on it is black (UI_HEX_BG)
static inline void uiSolidBtnStyle(lv_obj_t *btn, uint32_t hex) {
    const lv_style_selector_t sel[2] = { LV_PART_MAIN, (lv_style_selector_t)LV_PART_MAIN | LV_STATE_PRESSED };
    for (int i = 0; i < 2; i++) {
        const lv_color_t c = lv_color_hex(i == 0 ? hex : UI_MIX_HEX(hex, 80));
        lv_obj_set_style_bg_color(btn, c, sel[i]);
        lv_obj_set_style_bg_opa(btn, LV_OPA_COVER, sel[i]);
        lv_obj_set_style_border_color(btn, c, sel[i]);
    }
}

// Helper: standard Back button used system-wide
static inline UiToneBtn uiCreateBackBtn(lv_obj_t *parent, int32_t h, lv_event_cb_t cb, int32_t w = UI_CONTENT_W) {
    UiToneBtn b = uiCreateToneBtn(parent, w, h, UI_TONE_SILVER);
    lv_obj_align(b.btn, LV_ALIGN_BOTTOM_MID, 0, 0);
    lv_obj_set_style_border_color(b.btn, lv_color_hex(UI_HEX_ORANGE), LV_PART_MAIN | LV_STATE_PRESSED);   // pressed border: orange
    if (cb) lv_obj_add_event_cb(b.btn, cb, LV_EVENT_CLICKED, nullptr);
    // Orange "<" symbol (own label) + gray BACK text; the group is centered in the button
    lv_obj_t *lbl = lv_label_create(b.btn);
    lv_label_set_text(lbl, uiTr(STR_BACK));
    lv_obj_set_style_text_font(lbl, UI_FONT_T3, LV_PART_MAIN);
    lv_obj_set_style_text_color(lbl, lv_color_hex(UI_HEX_TEXT_SUB), LV_PART_MAIN);
    lv_obj_t *arr = lv_label_create(b.btn);
    lv_label_set_text(arr, LV_SYMBOL_LEFT);
    lv_obj_set_style_text_font(arr, UI_FONT_T3, LV_PART_MAIN);
    lv_obj_set_style_text_color(arr, lv_color_hex(UI_HEX_ORANGE), LV_PART_MAIN);
    lv_obj_update_layout(lbl);
    lv_obj_update_layout(arr);
    const int32_t gap = 10;
    const int32_t total = lv_obj_get_width(arr) + gap + lv_obj_get_width(lbl);
    lv_obj_align(arr, LV_ALIGN_CENTER, -(total / 2) + lv_obj_get_width(arr) / 2, 0);
    lv_obj_align(lbl, LV_ALIGN_CENTER, (total / 2) - lv_obj_get_width(lbl) / 2, 0);
    return b;
}

