// ============================================================================
// 6. Shared 5 s confirmation MODAL for END & DR (216x136 px)
// ============================================================================
struct UiConfirmPopup {
    lv_obj_t *backdrop = nullptr;
    lv_obj_t *panel    = nullptr;
    lv_obj_t *bar      = nullptr;
    lv_obj_t *lblSec   = nullptr;
    uint32_t  startMs  = 0;
    int       lastSec  = -1;
    void (*onConfirm)() = nullptr;
};

static inline bool uiConfirmIsOpen(const UiConfirmPopup &p) {
    return p.backdrop != nullptr;
}

static inline void uiConfirmClose(UiConfirmPopup &p) {
    if (p.backdrop) {
        lv_obj_delete(p.backdrop);
        p.backdrop = nullptr;
    }
    p.panel     = nullptr;
    p.bar       = nullptr;
    p.lblSec    = nullptr;
    p.startMs   = 0;
    p.lastSec   = -1;
    p.onConfirm = nullptr;
}

static void uiConfirmCancelCb(lv_event_t *e) {
    UiConfirmPopup *p = static_cast<UiConfirmPopup*>(lv_event_get_user_data(e));
    if (p) uiConfirmClose(*p);
}

static void uiConfirmOkCb(lv_event_t *e) {
    UiConfirmPopup *p = static_cast<UiConfirmPopup*>(lv_event_get_user_data(e));
    if (!p) return;
    void (*cb)() = p->onConfirm;
    uiConfirmClose(*p);
    if (cb) cb();
}

static inline void uiConfirmOpen(UiConfirmPopup &p, lv_obj_t *parentRoot,
                                 const char *title, void (*onConfirmCb)()) {
    uiConfirmClose(p);
    p.startMs   = millis();
    p.lastSec   = 5;
    p.onConfirm = onConfirmCb;

    lv_obj_t *bg = lv_obj_create(parentRoot);
    lv_obj_remove_style_all(bg);
    lv_obj_set_size(bg, UI_SCR_W, UI_SCR_H);
    lv_obj_set_pos(bg, 0, 0);
    lv_obj_set_style_bg_color(bg, lv_color_hex(0x000000), LV_PART_MAIN);
    lv_obj_set_style_bg_opa(bg, LV_OPA_70, LV_PART_MAIN);
    lv_obj_add_flag(bg, LV_OBJ_FLAG_CLICKABLE);
    lv_obj_remove_flag(bg, LV_OBJ_FLAG_SCROLLABLE);
    p.backdrop = bg;

    // 216x136 frame, centered, dark fill, 2 px red border
    lv_obj_t *box = uiCreateCard(bg, 216, 136);
    lv_obj_center(box);
    lv_obj_set_style_bg_color(box, lv_color_hex(UI_HEX_CARD), LV_PART_MAIN);
    lv_obj_set_style_border_width(box, 2, LV_PART_MAIN);
    lv_obj_set_style_border_color(box, lv_color_hex(UI_HEX_RED), LV_PART_MAIN);
    lv_obj_set_style_pad_all(box, 8, LV_PART_MAIN);
    lv_obj_add_flag(box, LV_OBJ_FLAG_CLICKABLE);
    p.panel = box;

    // Lower-case title (per UILang) in UI_FONT_T3
    lv_obj_t *lt = lv_label_create(box);
    lv_label_set_text(lt, title ? title : "");
    lv_obj_set_style_text_font(lt, UI_FONT_T3, LV_PART_MAIN);
    lv_obj_set_style_text_color(lt, lv_color_hex(UI_HEX_TEXT), LV_PART_MAIN);
    lv_obj_align(lt, LV_ALIGN_TOP_MID, 0, 2);

    // Red countdown bar over 5000 ms + seconds left (5s..1s).
    // The group (bar + number) is in one flex row: bar and number vertically centered with each other, the group centered horizontally,
    // and the row centered between the bottom of the title and the top of the two bottom buttons.
    lv_obj_update_layout(lt);
    const int32_t rowH    = 24;
    const int32_t gapTop  = 2 + lv_obj_get_height(lt);     // bottom of the title (title at y = 2)
    const int32_t gapBot  = (136 - 4 - 16) - 48;           // top of the two bottom buttons (content height 116, button height 48)
    const int32_t rowY    = gapTop + ((gapBot - gapTop) - rowH) / 2;

    lv_obj_t *row = lv_obj_create(box);
    lv_obj_remove_style_all(row);
    lv_obj_remove_flag(row, LV_OBJ_FLAG_CLICKABLE);
    lv_obj_remove_flag(row, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_set_size(row, LV_PCT(100), rowH);
    lv_obj_align(row, LV_ALIGN_TOP_MID, 0, rowY);
    lv_obj_set_flex_flow(row, LV_FLEX_FLOW_ROW);
    lv_obj_set_flex_align(row, LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);
    lv_obj_set_style_pad_column(row, 8, LV_PART_MAIN);

    p.bar = lv_bar_create(row);
    lv_obj_remove_style_all(p.bar);
    lv_obj_set_size(p.bar, 140, 10);
    lv_bar_set_range(p.bar, 0, 100);
    lv_bar_set_value(p.bar, 100, LV_ANIM_OFF);
    lv_obj_set_style_radius(p.bar, LV_RADIUS_CIRCLE, LV_PART_MAIN);
    lv_obj_set_style_bg_color(p.bar, lv_color_hex(UI_HEX_RED_OFF), LV_PART_MAIN);
    lv_obj_set_style_bg_opa(p.bar, LV_OPA_COVER, LV_PART_MAIN);
    lv_obj_set_style_radius(p.bar, LV_RADIUS_CIRCLE, LV_PART_INDICATOR);
    lv_obj_set_style_bg_color(p.bar, lv_color_hex(UI_HEX_RED), LV_PART_INDICATOR);
    lv_obj_set_style_bg_opa(p.bar, LV_OPA_COVER, LV_PART_INDICATOR);

    p.lblSec = lv_label_create(row);
    lv_label_set_text(p.lblSec, "5s");
    lv_obj_set_width(p.lblSec, 30);                          // fixed width: changing 5s..1s does not shift the group
    lv_obj_set_style_text_align(p.lblSec, LV_TEXT_ALIGN_CENTER, LV_PART_MAIN);
    lv_obj_set_style_text_font(p.lblSec, UI_FONT_T4, LV_PART_MAIN);
    lv_obj_set_style_text_color(p.lblSec, lv_color_hex(UI_HEX_RED), LV_PART_MAIN);

    // 2 bottom buttons: CANCEL (UI_TONE_SILVER) | CONFIRM (UI_TONE_RED), same font UI_FONT_T3
    // Usable width in the panel: 216 - 4 (border) - 16 (pad) = 196 px -> 76 + 6 + 114 = 196 px
    UiToneBtn bCancel = uiCreateToneBtn(box, 76, 48, UI_TONE_SILVER);
    lv_obj_align(bCancel.btn, LV_ALIGN_BOTTOM_LEFT, 0, 0);
    lv_obj_add_event_cb(bCancel.btn, uiConfirmCancelCb, LV_EVENT_CLICKED, &p);
    lv_obj_t *lc = lv_label_create(bCancel.btn);
    lv_label_set_text(lc, uiTr(STR_CANCEL));
    lv_obj_set_style_text_font(lc, UI_FONT_T3, LV_PART_MAIN);
    lv_obj_set_style_text_color(lc, lv_color_hex(UI_HEX_TEXT_SUB), LV_PART_MAIN);
    lv_obj_center(lc);

    UiToneBtn bOk = uiCreateToneBtn(box, 114, 48, UI_TONE_RED);
    lv_obj_align(bOk.btn, LV_ALIGN_BOTTOM_RIGHT, 0, 0);
    uiToneBtnSetOn(bOk, true);
    lv_obj_add_event_cb(bOk.btn, uiConfirmOkCb, LV_EVENT_CLICKED, &p);
    lv_obj_t *lo = lv_label_create(bOk.btn);
    lv_label_set_text(lo, uiTr(STR_CONFIRM));
    lv_obj_set_style_text_font(lo, UI_FONT_T3, LV_PART_MAIN);
    lv_obj_set_style_text_color(lo, lv_color_hex(UI_HEX_TEXT), LV_PART_MAIN);
    lv_obj_center(lo);
}

static inline void uiConfirmTick(UiConfirmPopup &p) {
    if (!p.backdrop || p.startMs == 0) return;
    uint32_t el = millis() - p.startMs;
    if (el >= UI_CONFIRM_MS) {
        uiConfirmClose(p);
        return;
    }
    if (p.bar) {
        int remPct = static_cast<int>(((UI_CONFIRM_MS - el) * 100UL) / UI_CONFIRM_MS);
        lv_bar_set_value(p.bar, remPct, LV_ANIM_OFF);
    }
    int secLeft = static_cast<int>((UI_CONFIRM_MS - el + 999UL) / 1000UL);
    if (secLeft < 1) secLeft = 1;
    if (secLeft > 5) secLeft = 5;
    if (secLeft != p.lastSec && p.lblSec) {
        p.lastSec = secLeft;
        lv_label_set_text_fmt(p.lblSec, "%ds", secLeft);
    }
}
